L000094	\title{
L000095	Chaotic fluctuations in a universal set of transmon qubit gates}
L000096	
L000097	\author{Daniel Basilewitsch}
L000098	\affiliation{
L000099	  Dahlem Center for Complex Quantum Systems and Fachbereich Physik, Freie
L000100	Universit\"{a}t Berlin, D-14195 Berlin, Germany }
L000101	
L000102	\author{Simon-Dominik B\"orner}
L000103	\affiliation{
L000104	  Institute for Theoretical Physics, University of Cologne, D-50937 Cologne,
L000105	Germany }
L000106	
L000107	\author{Christoph Berke}
L000108	\affiliation{
L000109	  Institute for Theoretical Physics, University of Cologne, D-50937 Cologne,
L000110	Germany }
